                    rs=[p[0] for p in comp];cs=[p[1] for p in comp]
                    h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                    if len(comp)==2*h+2*w-4 and h>=3 and w>=3:
                        res.append((min(rs),min(cs),h,w))
        return res
    noise_color=min(others,key=lambda c:sum(r.count(c) for r in g))
    fr={c:rects(c) for c in others if c!=noise_color}
    best=None;bestcells=-1
    for col,Rl in fr.items():
