        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def hollow_rects(g,col,H,W):
    seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==col and not seen[r][c]:
                st=[(r,c)];comp=[]
                while st:
                    x,y=st.pop()
                    if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                        seen[x][y]=True;comp.append((x,y))
                        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)): st.append((x+dx,y+dy))
                rs=[p[0] for p in comp];cs=[p[1] for p in comp]
                h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                if len(comp)==2*h+2*w-4 and h>=3 and w>=3:
                    res.append((min(rs),min(cs),h,w))
    return res
def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    frame=max(others,key=lambda c:sum(h*w for _,_,h,w in hollow_rects(g,c,H,W)))
    noise=min([c for c in others if c!=frame],key=lambda c:sum(r.count(c) for r in g))
    R=hollow_rects(g,frame,H,W)
    def ni(r0,c0,h,w):
        return sum(1 for i in range(1,h-1) for j in range(1,w-1) if g[r0+i][c0+j]==noise)
    def noise_has_bg(r0,c0,h,w):
        inter={g[r0+i][c0+j] for i in range(1,h-1) for j in range(1,w-1)}
        return noise in inter and bg in inter
    cands=[b for b in R if noise_has_bg(*b)]
    best=max(cands,key=lambda b:(ni(*b),b[2]*b[3]))
    r0,c0,h,w=best
    return [[noise if (i==0 or i==h-1 or j==0 or j==w-1) else g[r0+i][c0+j] for j in range(w)] for i in range(h)]
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
